    }
}

/// Returns the nth Fibonacci number, recursively.
fn fib(n: int) -> int {
    if n < 2 {
        return n
    }
    return fib(n - 1) + fib(n - 2)
}

/// Returns the first [count] Fibonacci numbers, with a loop.
fn sequence(count: int) -> [int] {
    var result: [int] = []
    var a = 0
    var b = 1
    for i in 0..count {
        result.push(a)
        let next = a + b
        a = b
        b = next
    }
    return result
}

fn main() {
    println("First 15: {sequence(15)}")
    println("fib(30) = {fib(30)}")
}

/// A bank account with a running history.
struct Account {
    owner: string
    balance: float = 0.0
    history: [string] = []

    fn deposit(amount: float) {
        balance += amount
        history.push("+{amount}")
    }

    fn withdraw(amount: float) -> bool {
        if amount > balance {
            history.push("declined {amount}")
            return false
        }
        balance -= amount
        history.push("-{amount}")
        return true
    }

    fn summary() -> string => "{owner}: {balance}"

    static fn opening(owner: string) -> Account {
        let account = Account(owner: owner)
        account.deposit(10.0)
        return account
    }
}

fn main() {
    let ann = Account.opening("Ann")
    ann.deposit(50.5)
    ann.withdraw(20)
    if !ann.withdraw(500) {
        println("Not enough money for that")
    }
    println(ann.summary())
    println("History: {ann.history}")

    // Structs are shared: both names refer to the same account.
    let same = ann
    same.deposit(1)
    println(ann.summary())
    println(ann)
}

/// A shape on a canvas.
enum Shape {
    circle(radius: float)
    rect(width: float, height: float)
    empty

    fn area() -> float => match self {
        circle(r) => 3.14 * r * r
        rect(w, h) => w * h
        empty => 0.0
    }

    fn name() -> string => match self {
        circle(_) => "circle"
        rect(_, _) => "rect"
        empty => "nothing"
    }

    static fn square(side: float) -> Shape => .rect(width: side, height: side)
}

/// The colour of a traffic light.
enum Light {
    red, yellow, green

    fn next() -> Light => match self {
        red => .green
        green => .yellow
        yellow => .red
    }
}

/// The outcome of reading a number.
enum Parsed {
    number(value: int)
    failed(reason: string)
}

fn parse(text: string) -> Parsed {
    if text == "" {
        return .failed(reason: "the text is empty")
    }
    if text.contains(" ") {
        return .failed(reason: "the text has spaces")
    }
    return .number(value: int(text))
}

fn main() {
    let shapes = [Shape.circle(radius: 1), .rect(width: 2, height: 3), Shape.square(2), .empty]
    var total = 0.0
    for s in shapes {
        println("{s.name()}: {s.area()}")
        total += s.area()
    }
    println("total area: {total}")
    println(shapes[1])

    var light = Light.red
    for i in 0..4 {
        print(light, "")
        light = light.next()
    }
    println()
    println("after 4 changes:", light, light == .green)

    for text in ["42", "", "4 2"] {
        match parse(text) {
            number(n) => println("{text} -> {n * 2}")
            failed(why) => println("{text} -> error: {why}")
        }
    }

    for code in [200, 404, 500] {
        let message = match code {
            200 => "ok"
            404 => "not found"
            _ => "error {code}"
        }
        println(code, message)
    }
}

/// A person in a small company.
struct Person {
    name: string
    manager: Person? = nil
    email: string? = nil

    fn contact() -> string => email ?? "no email"
}

/// Returns the person called [name], or nil.
fn find(people: [Person], name: string) -> Person? {
    for p in people {
        if p.name == name {
            return p
        }
    }
    return nil
}

/// Returns the number in [text], or nil when it isn't one.
fn parseAge(text: string) -> int? {
    if text == "" || text.contains(" ") {
        return nil
    }
    return int(text)
}

fn introduce(people: [Person], name: string) {
    guard let p = find(people, name) else {
        println("{name}: not found")
        return
    }
    let boss = p.manager?.name ?? "nobody"
    println("{p.name} reports to {boss}, {p.contact()}")
}

fn main() {
    let ceo = Person(name: "Maya", email: "maya@example.com")
    let lead = Person(name: "Omar", manager: ceo)
    let dev = Person(name: "Lena", manager: lead, email: "lena@example.com")
    let people = [ceo, lead, dev]

    for name in ["Lena", "Omar", "Maya", "Zed"] {
        introduce(people, name)
    }

    // Chains stop at the first nil.
    println(dev.manager?.manager?.name, ceo.manager?.manager?.name)

    if let boss = find(people, "Lena")?.manager {
        println("Lena's manager is {boss.name}")
    }

    var total = 0
    for text in ["31", "", "4 2", "27"] {
        let age = parseAge(text)
        println("'{text}' ->", age)
        total += age ?? 0
    }
    println("total:", total)

    var selected: Person? = nil
    println(selected == nil)
    selected = dev
    println(selected?.name ?? "none")
}

enum LoadError {
    notFound(path: string)
    denied
}

fn parsePort(s: string) throws -> int {
    if s == "" {
        throw Error("empty port")
    }
    let n = int(s)
    if n < 1 || n > 65535 {
        throw Error("port {n} out of range")
    }
    return n
}

fn open(path: string) throws(LoadError) -> string {
    if path == "secret" {
        throw .denied
    }
    if path != "app.cfg" {
        throw .notFound(path: path)
    }
    return "8080"
}

fn load(path: string) throws -> int {
    let text = try open(path)
    return try parsePort(text)
}

struct Server {
    port: int

    fn start() throws {
        if port == 0 {
            throw Error("no port")
        }
        println("listening on {port}")
    }
}

fn twice(f: fn(int) throws -> int, x: int) throws -> int => try f(try f(x))

fn main() throws {
    println(try load("app.cfg"))
    let a = try load("x.cfg") catch e {
        println("failed: {e.message}")
        0
    }
    println(a)
    let b = try open("secret") catch e {
        match e {
            notFound(p) => "missing {p}"
            denied => "denied"
        }
    }
    println(b)
    let c = try? parsePort("70000") ?? 1
    let d = try? parsePort("22")
    println(c, d)
    for s in ["1", "", "3"] {
        let n = try parsePort(s) catch {
            continue
        }
        print(n, "")
    }
    println()
    try Server(port: 9).start()
    try Server(port: 0).start() catch e {
        println("server: {e.message}")
    }
    let half = fn(x: int) throws -> int {
        if x % 2 == 1 {
            throw Error("odd {x}")
        }
        return x / 2
    }
    println(try twice(half, 12))
    println(try twice(half, 6) catch e { println(e.message); -1 })
    println(try twice(fn(x) => x + 1, 1))
}

/// A button that runs [onTap] when tapped.
struct Button {
    title: string
    onTap: fn()

    fn tap() {
        println("[{title}] tapped")
        onTap()
    }
}

/// Runs [action] [times] times.
fn repeat(times: int, action: fn()) {
    for i in 0..times {
        action()
    }
}

/// Returns a function that adds [n] to its argument.
fn adder(n: int) -> fn(int) -> int => fn(x) => x + n

/// Returns a counter: each call returns the next number.
fn makeCounter() -> fn() -> int {
    var count = 0
    return fn() -> int {
        count += 1
        return count
    }
}

fn main() {
    // Closures stored in variables.
    let double = fn(x: int) -> int => x * 2
    let greet = fn(name: string) {
        println("Hello, {name}!")
    }
    greet("Vex")
    println("double(21) = {double(21)}")

    // Closures that capture variables share them with the code around them.
    var taps = 0
    let add = Button(title: "Add") { taps += 1 }
    add.tap()
    add.tap()
    repeat(3) { taps += 10 }
    println("taps = {taps}")

    // Functions that return functions.
    let addFive = adder(5)
    println("addFive(10) = {addFive(10)}")
    let next = makeCounter()
    println("counter: {next()} {next()} {next()}")

    // filter and map take closures.
    let scores = [42, 7, 19, 88, 3, 56]
    let passed = scores.filter(fn(s) => s >= 40)
    let labels = passed.map(fn(s) => "{s} pts")
    println("passed: {passed}")
    println("labels: {labels}")
}

// Counts words, groups them by length and keeps a small inventory.

enum Size { small, large }

fn wordCounts(text: string) -> [string: int] {
    var counts: [string: int] = [:]
    for word in text.lower().split(" ") {
        if word != "" {
            counts[word] = (counts[word] ?? 0) + 1
        }
    }
    return counts
}

fn main() {
    let counts = wordCounts("the cat and the hat and the bat")
    println(counts)
    println("the: {counts["the"] ?? 0}, dog: {counts["dog"] ?? 0}")

    var byLength: [int: [string]] = [:]
    for word, n in counts {
        var group = byLength[word.len] ?? []
        group.push(word)
        byLength[word.len] = group
    }
    for length, words in byLength {
        println("{length} letters: {words}")
    }

    var stock = ["apples": 5, "pears": 0, "plums": 12]
    stock["figs"] = 3
    if let gone = stock.remove("pears") {
        println("removed pears ({gone} left)")
    }
    var total = 0
    for item, n in stock {
        total += n
    }
    println(stock.keys, total)

    let sizes: [Size: string] = [.small: "S", .large: "L"]
    println(sizes[.large] ?? "?", sizes.contains(.small))
}

// Generic functions and structs. Each use with new types compiles to its
// own specialised copy, so generic code runs as fast as hand-written code.

struct Stack<T> {
    items: [T] = []

    fn push(item: T) {
        items.push(item)
    }

    fn pop() -> T? {
        if items.len == 0 {
            return nil
        }
        return items.pop()
    }

    fn peek() -> T? {
        if items.len == 0 {
            return nil
        }
        return items[items.len - 1]
    }
}

struct Pair<A, B> {
    first: A
    second: B
}

fn largest<T: Comparable>(xs: [T]) -> T? {
    if xs.len == 0 {
        return nil
    }
    var best = xs[0]
    for x in xs {
        if x > best {
            best = x
        }
    }
    return best
}

fn frequencies<T: Hashable>(xs: [T]) -> [T: int] {
    var counts: [T: int] = [:]
    for x in xs {
        counts[x] = (counts[x] ?? 0) + 1
    }
    return counts
}

fn zip<A, B>(xs: [A], ys: [B]) -> [Pair<A, B>] {
    var out: [Pair<A, B>] = []
    var i = 0
    while i < xs.len && i < ys.len {
        out.push(Pair(first: xs[i], second: ys[i]))
        i += 1
    }
    return out
}

fn main() {
    let history = Stack<string>()
    history.push("home")
    history.push("settings")
    println(history.peek() ?? "-", history.items)
    println(history.pop(), history.pop(), history.pop())

    let numbers = Stack<int>()
    for n in 1..=3 {
        numbers.push(n * 10)
    }
    println(numbers.items)

    println(largest([4, 17, 9]), largest(["kiwi", "apple"]), largest<float>([]))
    println(frequencies(["a", "b", "a", "c", "a"]))

    let pairs = zip(["ann", "bob", "cat"], [31, 25])
    for p in pairs {
        println("{p.first} is {p.second}")
    }
    println(pairs[0])
}

// Interfaces: structs promise methods, and code works with any struct that
// keeps the promise.

interface Shape {
    fn area() -> float
    fn name() -> string => "shape"

    // Defaults can call the other methods, which use each struct's own.
    fn summary() -> string => "{name()}: {area()}"
}

interface Resizable {
    fn resize(by: float)
}

struct Circle: Shape, Resizable {
    radius: float

    fn area() -> float => 3.14 * radius * radius
    fn name() -> string => "circle"
    fn resize(by: float) {
        radius = radius * by
    }
}

struct Rect: Shape, Resizable {
    width: float
    height: float

    fn area() -> float => width * height
    fn resize(by: float) {
        width = width * by
        height = height * by
    }
}

fn totalArea(shapes: [Shape]) -> float {
    var total = 0.0
    for s in shapes {
        total += s.area()
    }
    return total
}

// A generic constrained by an interface is compiled for each type, so the
// calls inside go straight to that type's methods.
fn largest<T: Shape>(items: [T]) -> T? {
    if items.len == 0 {
        return nil
    }
    var best = items[0]
    for item in items {
        if item.area() > best.area() {
            best = item
        }
    }
    return best
}

fn main() {
    let c = Circle(radius: 1.0)
    let r = Rect(width: 2.0, height: 3.0)
    let shapes: [Shape] = [c, r]
    for s in shapes {
        println(s.summary())
    }
    println("total:", totalArea(shapes))

    let resizable: [Resizable] = [c, r]
    for x in resizable {
        x.resize(by: 2.0)
    }
    println(shapes)

    println(largest([Rect(width: 1.0, height: 1.0), Rect(width: 5.0, height: 2.0)]))
    if let big = largest(shapes) {
        println("largest:", big.name())
    }
}

/// Returns the primes below [limit] with the Sieve of Eratosthenes.
fn primes(limit: int) -> [int] {
    var isPrime: [bool] = []
    for i in 0..limit {
        isPrime.push(i >= 2)
    }
    var found: [int] = []
    for n in 2..limit {
        if isPrime[n] {
            found.push(n)
            var m = n * n
            while m < limit {
                isPrime[m] = false
                m += n
            }
        }
    }
    return found
}

fn main() {
    let small = primes(50)
    println("Primes below 50: {small}")
    println("There are {primes(1000000).len} primes below one million")
}

/// Sorts [xs] in place by repeatedly swapping neighbours that are out of order.
fn bubbleSort(xs: [int]) {
    for i in 0..xs.len {
        var swapped = false
        for j in 0..xs.len - 1 - i {
            if xs[j] > xs[j + 1] {
                let tmp = xs[j]
                xs[j] = xs[j + 1]
                xs[j + 1] = tmp
                swapped = true
            }
        }
        if !swapped {
            break
        }
    }
}

/// Sorts [words] in place by inserting each word into the sorted part before it.
fn insertionSort(words: [string]) {
    for i in 1..words.len {
        let word = words[i]
        var j = i - 1
        while j >= 0 && words[j] > word {
            words[j + 1] = words[j]
            j -= 1
        }
        words[j + 1] = word
    }
}

/// Returns a new sorted list, leaving [xs] unchanged.
fn sorted(xs: [int]) -> [int] {
    var copy: [int] = []
    for x in xs {
        copy.push(x)
    }
    bubbleSort(copy)
    return copy
}

fn main() {
    let numbers = [42, 7, 19, 88, 3, 56, -4, 19]
    let ordered = sorted(numbers)
    println("Original: {numbers}")
    println("Sorted:   {ordered}")

    var words = "pear,apple,fig,banana,cherry".split(",")
    insertionSort(words)
    println("Words:    {words}")
}

// Reads a name and numbers from the keyboard, until an empty line.

fn main() {
    let name = input("What's your name? ")
    println("Hi, {name}! Enter numbers, one per line. Leave a line empty to finish.")

    var numbers: [float] = []
    while true {
        let line = input("> ")
        if line == "" {
            break
        }
        numbers.push(float(line))
    }

    if numbers.len == 0 {
        println("No numbers entered.")
        return
    }
    var total = 0.0
    for n in numbers {
        total += n
    }
    println("{name}, you entered {numbers.len} numbers.")
    println("Sum: {total}, average: {total / float(numbers.len)}")
}
